window.predictPM25WithGBM = function(featureObj) {
  const m = window.AURA_ML_MODEL;
  const x = m.features.map(f => Number(featureObj[f] ?? 0));
  let score = m.base_score;
  const lr = m.learning_rate;
  for (let t = 0; t < m.trees.length; t++) {
    const nodes = m.trees[t];
    let idx = 0;
    while (nodes[idx][0] !== -1) {
      idx = x[nodes[idx][2]] <= nodes[idx][3] ? nodes[idx][0] : nodes[idx][1];
    }
    score += lr * nodes[idx][4];
  }
  return Math.max(5.0, Math.round(score * 10) / 10);
};
